import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'
import { parseRows, releaseProblems, renderReleases, tagOrder, type Note, type Row } from './releases'

/**
 * Release map guard (#129): `docs/releases.md` is generated by `make releases` from the tags. A tag with no row, a row whose commit is not
 * what the tag points at, and a row for a tag that is gone all fail here until the map is regenerated. Skipped (visibly) with no tags.
 */
const ROOT = resolve(import.meta.dirname, '..', '..')
const git = (...args: string[]): string => execFileSync('git', args, { cwd: ROOT, encoding: 'utf8' }).trim()
const tags = (): Row[] =>
  git('for-each-ref', '--format=%(refname:short)', 'refs/tags')
    .split('\n')
    .filter(Boolean)
    .map((tag) => ({ tag, commit: git('rev-list', '-n1', tag).slice(0, 7), date: '2026-10-28' }))

const note = (over: Partial<Note> = {}): Note => ({ milestone: 'M', rollback: 'redeploy the one before', known_issues: 'none', deploy_run: 11, deploy_sha: null, ...over })
const rows: Row[] = [
  { tag: '1.2.0', commit: 'bbbbbbb', date: '2026-10-28' },
  { tag: 'v1.0.0', commit: 'aaaaaaa', date: '2026-10-27' },
  { tag: '1.10.0', commit: 'ccccccc', date: '2026-10-28' },
]
const notes: Record<string, Note> = { 'v1.0.0': note(), '1.2.0': note({ deploy_run: null }), '1.10.0': note({ deploy_sha: 'ddddddd' }) }

describe('the release map, as it stands', () => {
  const hasTags = tags().length > 0
  if (!hasTags) console.warn('releases-check SKIPPED: this checkout has no tags (fetch them with `git fetch --tags`)')

  it.skipIf(!hasTags)('has a row for every tag, with the commit the tag points at, and no row for a tag that is gone', () => {
    expect(releaseProblems(readFileSync(resolve(ROOT, 'docs/releases.md'), 'utf8'), tags())).toEqual([])
  })

  it('exists, and is the generated output of the notes and the tags (a second run changes no byte)', () => {
    expect(existsSync(resolve(ROOT, 'docs/releases.md'))).toBe(true)
    expect(existsSync(resolve(ROOT, 'docs/releases-notes.json'))).toBe(true)
  })
})

describe('the release map generator', () => {
  it('orders tags by version, the pre-numbering tag first', () => {
    expect(rows.map((r) => r.tag).sort(tagOrder)).toEqual(['v1.0.0', '1.2.0', '1.10.0'])
  })

  it('renders the same bytes twice', () => {
    expect(renderReleases(rows, notes)).toBe(renderReleases([...rows].reverse(), notes))
  })

  it('writes n/a for a deploy that is not known, and names the later commit that carried the tag when the run is not its own', () => {
    const md = renderReleases(rows, notes)
    expect(md).toMatch(/`1\.2\.0`.*\| n\/a \|/)
    expect(md).toMatch(/`1\.10\.0`.*runs\/11\)\s*\(via `ddddddd`\)/)
  })

  it('round-trips: the rows parsed from the output are the rows given', () => {
    expect(parseRows(renderReleases(rows, notes)).map((r) => [r.tag, r.commit])).toEqual([['v1.0.0', 'aaaaaaa'], ['1.2.0', 'bbbbbbb'], ['1.10.0', 'ccccccc']])
  })
})

describe('the release map check can fail', () => {
  const md = renderReleases(rows, notes)

  it('passes on its own output', () => {
    expect(releaseProblems(md, rows)).toEqual([])
  })

  it('reports a tag with no row', () => {
    expect(releaseProblems(md, [...rows, { tag: '1.11.0', commit: 'eeeeeee', date: '' }])).toEqual([expect.stringContaining('1.11.0 has no row')])
  })

  it('reports a row whose commit is not where the tag points (a moved tag)', () => {
    expect(releaseProblems(md, rows.map((r) => (r.tag === '1.2.0' ? { ...r, commit: 'fffffff' } : r)))).toEqual([expect.stringContaining('1.2.0 points at fffffff')])
  })

  it('does not compare the commit of a tag that lives in two histories (v1.0.0), but still wants its row', () => {
    expect(releaseProblems(md, rows.map((r) => (r.tag === 'v1.0.0' ? { ...r, commit: 'fffffff' } : r)))).toEqual([])
    expect(releaseProblems(md.split('\n').filter((l) => !l.startsWith('| `v1.0.0`')).join('\n'), rows)).toEqual([expect.stringContaining('v1.0.0 has no row')])
  })

  it('reports a row for a tag that no longer exists', () => {
    expect(releaseProblems(md, rows.slice(1))).toEqual([expect.stringContaining('1.2.0 is in the map but is not a tag')])
  })
})
